async function extractDocx(path){
  const blob = await readFileBinary(path);
  const buf = new Uint8Array(await blob.arrayBuffer());
  // Use JSZip via CDN? Not available. Parse zip manually.
  // Minimal zip local-file parser for document.xml
  const dv = new DataView(buf.buffer);
  let out = {};
  // find End of Central Directory
  // Simpler: scan for local file headers PK\x03\x04
  let i=0;
  const files={};
  while(i < buf.length-4){
    if(buf[i]===0x50&&buf[i+1]===0x4b&&buf[i+2]===0x03&&buf[i+3]===0x04){
      const method=dv.getUint16(i+8,true);
      const compSize=dv.getUint32(i+18,true);
      const nameLen=dv.getUint16(i+26,true);
      const extraLen=dv.getUint16(i+28,true);
      const nameStart=i+30;
      const name=new TextDecoder().decode(buf.slice(nameStart,nameStart+nameLen));
      const dataStart=nameStart+nameLen+extraLen;
      const comp=buf.slice(dataStart,dataStart+compSize);
      files[name]={method,comp};
      i=dataStart+compSize;
    } else i++;
  }
  return files;
}
const files = await extractDocx('uploads/BRAINSTORM EDITS OpportunityDesigned_Brand_Marketing_Playbook.docx');
log('entries:', Object.keys(files).join(', '));
const doc = files['word/document.xml'];
if(doc){
  let bytes = doc.comp;
  if(doc.method===8){
    const ds = new DecompressionStream('deflate-raw');
    const stream = new Blob([bytes]).stream().pipeThrough(ds);
    bytes = new Uint8Array(await new Response(stream).arrayBuffer());
  }
  const xml = new TextDecoder().decode(bytes);
  // strip tags but keep paragraph breaks
  let text = xml.replace(/<\/w:p>/g,'\n').replace(/<w:tab\/>/g,'\t').replace(/<[^>]+>/g,'');
  text = text.replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&apos;/g,"'");
  await saveFile('research/playbook.txt', text);
  log('playbook length:', text.length);
  log(text.slice(0,3000));
}

