/* Opportunity Designed — Color tokens
   Palette from README.txt + built website. Warm, earthy, near-monochrome
   with a single violet accent. Parchment (light) and Obsidian (dark) are
   the two brand surfaces. */
:root {
  /* Base neutrals — warm */
  --black: #000000;
  --obsidian: #1C1916;      /* warm near-black — brand dark surface */
  --obsidian-2: #262019;    /* raised surface on dark */
  --ink: #1A1A1A;           /* body text on light */
  --dusk: #8A7D6E;          /* muted / secondary text (warm taupe) */
  --dusk-2: #A99C8C;        /* lighter muted on dark */
  --parchment: #F7F2E8;     /* brand light background */
  --parchment-2: #EFE8D9;   /* card / recessed on parchment */
  --paper: #FBF8F1;         /* lightest raised card on parchment */
  --white: #FFFFFF;

  /* Accent — violet */
  --violet: #5C4A82;        /* brand accent */
  --violet-deep: #463969;   /* pressed / hover-dark accent */
  --violet-light: #B49CE0;  /* accent on dark surfaces, links */
  --violet-tint: #E9E2F2;   /* faint accent wash on light */

  /* Hairlines & rules */
  --line-ink: rgba(26,26,26,0.16);   /* rule on parchment */
  --line-ink-strong: rgba(26,26,26,0.32);
  --line-light: rgba(247,242,232,0.16); /* rule on obsidian */
  --line-light-strong: rgba(247,242,232,0.30);

  /* ---- Semantic aliases ---- */
  --surface-page: var(--parchment);
  --surface-card: var(--paper);
  --surface-sunken: var(--parchment-2);
  --surface-dark: var(--obsidian);
  --surface-dark-raised: var(--obsidian-2);

  --text-body: var(--ink);
  --text-muted: var(--dusk);
  --text-on-dark: var(--parchment);
  --text-muted-on-dark: var(--dusk-2);
  --text-accent: var(--violet);
  --text-accent-on-dark: var(--violet-light);
  --text-link: var(--violet);
  --text-link-on-dark: var(--violet-light);

  --border-hair: var(--line-ink);
  --border-strong: var(--line-ink-strong);
  --border-hair-on-dark: var(--line-light);

  --accent: var(--violet);
  --accent-hover: var(--violet-deep);
  --accent-contrast: var(--parchment);
}

/* Opportunity Designed — Webfonts
   Anton: single-weight condensed display (headlines, section numbers).
   Inter: body & UI, light-forward (300 is the brand default weight). */
@font-face {
  font-family: 'Anton';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url('../assets/fonts/anton-latin-400-normal.woff2') format('woff2');
}
@font-face {
  font-family: 'Inter';
  font-style: normal;
  font-weight: 300;
  font-display: swap;
  src: url('../assets/fonts/inter-latin-300-normal.woff2') format('woff2');
}
@font-face {
  font-family: 'Inter';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url('../assets/fonts/inter-latin-400-normal.woff2') format('woff2');
}
@font-face {
  font-family: 'Inter';
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url('../assets/fonts/inter-latin-500-normal.woff2') format('woff2');
}
@font-face {
  font-family: 'Inter';
  font-style: normal;
  font-weight: 600;
  font-display: swap;
  src: url('../assets/fonts/inter-latin-600-normal.woff2') format('woff2');
}
@font-face {
  font-family: 'Inter';
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: url('../assets/fonts/inter-latin-700-normal.woff2') format('woff2');
}

/* Opportunity Designed — Typography tokens
   Display: Anton (condensed, all-caps or sentence case, tight leading).
   Body/UI: Inter, light-forward. Eyebrows & meta are uppercase tracked. */
:root {
  --font-display: 'Anton', 'Arial Narrow', sans-serif;
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-mono: ui-monospace, 'SF Mono', 'Roboto Mono', Menlo, monospace;

  /* Body weights — brand leans LIGHT */
  --fw-light: 300;
  --fw-regular: 400;
  --fw-medium: 500;
  --fw-semibold: 600;
  --fw-bold: 700;

  /* Type scale (px) */
  --fs-hero: clamp(3.5rem, 9vw, 8.5rem);   /* Anton hero */
  --fs-display: clamp(2.5rem, 5vw, 4.5rem);/* Anton section statements */
  --fs-h1: clamp(2rem, 4vw, 3.25rem);
  --fs-h2: clamp(1.6rem, 3vw, 2.4rem);
  --fs-h3: 1.5rem;
  --fs-h4: 1.15rem;
  --fs-lead: 1.25rem;   /* intro paragraphs */
  --fs-body: 1.0625rem; /* 17px base body */
  --fs-sm: 0.9375rem;
  --fs-meta: 0.75rem;   /* eyebrows, fig captions, codes */
  --fs-micro: 0.6875rem;

  --lh-tight: 0.98;   /* Anton display */
  --lh-snug: 1.15;
  --lh-body: 1.6;
  --lh-relaxed: 1.75;

  /* Tracking */
  --tr-display: -0.01em;
  --tr-tight: -0.02em;
  --tr-normal: 0;
  --tr-eyebrow: 0.22em;  /* uppercase eyebrows / meta labels */
  --tr-wide: 0.08em;

  /* Semantic */
  --text-eyebrow-transform: uppercase;
}

/* Opportunity Designed — Spacing, radius, borders, shadow, motion
   Blueprint aesthetic: crisp hairlines, minimal radii, restrained shadow.
   Layout leans on generous margins and section rules, not heavy cards. */
:root {
  /* Spacing scale (4px base) */
  --sp-1: 4px;
  --sp-2: 8px;
  --sp-3: 12px;
  --sp-4: 16px;
  --sp-5: 24px;
  --sp-6: 32px;
  --sp-7: 48px;
  --sp-8: 64px;
  --sp-9: 96px;
  --sp-10: 128px;

  /* Page margin — wide, architectural */
  --mx: clamp(20px, 6vw, 120px);
  --section-y: clamp(56px, 9vh, 120px);
  --maxw: 1360px;

  /* Radius — nearly square; brand is technical, not soft */
  --r-none: 0;
  --r-sm: 2px;
  --r-md: 4px;
  --r-lg: 8px;
  --r-pill: 999px;

  /* Border widths */
  --bw-hair: 1px;
  --bw-med: 1.5px;
  --bw-thick: 2px;

  /* Shadows — subtle, warm-tinted, used sparingly */
  --shadow-sm: 0 1px 2px rgba(28,25,22,0.06);
  --shadow-md: 0 8px 24px rgba(28,25,22,0.08);
  --shadow-lg: 0 24px 60px rgba(28,25,22,0.12);
  --shadow-focus: 0 0 0 3px rgba(92,74,130,0.30);

  /* Grain / texture opacity */
  --grain-opacity: 0.05;

  /* Motion — calm, controlled. No bounce. */
  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --dur-fast: 140ms;
  --dur-base: 240ms;
  --dur-slow: 480ms;

  /* Corner-tick size (blueprint "plate" registration marks) */
  --tick-len: 14px;
  --tick-w: 1.5px;
}

/* Opportunity Designed — global stylesheet entry point.
   Consumers link THIS file. It is @import lines only. */
@import "tokens/fonts.css";
@import "tokens/colors.css";
@import "tokens/typography.css";
@import "tokens/layout.css";

