import React, { useState } from "react";

/**
 * Opportunity Designed — Button
 * Blueprint-register CTA. Filled (violet) or outline; light or dark surface.
 * Optional trailing arrow. No bounce; hover darkens/fills, press nudges 1px.
 */
export function Button({
  children,
  variant = "fill",
  size = "md",
  onDark = false,
  arrow = false,
  href,
  disabled = false,
  onClick,
  ...rest
}) {
  const [hover, setHover] = useState(false);
  const [press, setPress] = useState(false);

  const pad = size === "sm" ? "10px 18px" : size === "lg" ? "18px 34px" : "14px 26px";
  const fs = size === "sm" ? "0.8125rem" : size === "lg" ? "1rem" : "0.9375rem";

  const base = {
    display: "inline-flex",
    alignItems: "center",
    gap: "0.6em",
    fontFamily: "var(--font-sans)",
    fontWeight: 500,
    fontSize: fs,
    letterSpacing: "0.02em",
    lineHeight: 1,
    padding: pad,
    border: "1.5px solid transparent",
    borderRadius: "var(--r-md)",
    cursor: disabled ? "not-allowed" : "pointer",
    textDecoration: "none",
    transition: "background var(--dur-fast) var(--ease-out), color var(--dur-fast) var(--ease-out), border-color var(--dur-fast) var(--ease-out), transform var(--dur-fast) var(--ease-out)",
    transform: press && !disabled ? "translateY(1px)" : "translateY(0)",
    opacity: disabled ? 0.45 : 1,
    whiteSpace: "nowrap",
  };

  let skin;
  if (variant === "fill") {
    skin = {
      background: hover ? "var(--violet-deep)" : "var(--violet)",
      color: "var(--parchment)",
      borderColor: hover ? "var(--violet-deep)" : "var(--violet)",
    };
  } else {
    // outline
    const line = onDark ? "var(--parchment)" : "var(--ink)";
    const fillHover = onDark ? "var(--parchment)" : "var(--ink)";
    const textHover = onDark ? "var(--obsidian)" : "var(--parchment)";
    skin = {
      background: hover ? fillHover : "transparent",
      color: hover ? textHover : (onDark ? "var(--parchment)" : "var(--ink)"),
      borderColor: line,
    };
  }

  const Tag = href ? "a" : "button";
  return (
    <Tag
      href={href}
      onClick={disabled ? undefined : onClick}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => { setHover(false); setPress(false); }}
      onMouseDown={() => setPress(true)}
      onMouseUp={() => setPress(false)}
      style={{ ...base, ...skin }}
      {...rest}
    >
      {children}
      {arrow && <span aria-hidden="true" style={{ transition: "transform var(--dur-base) var(--ease-out)", transform: hover ? "translateX(3px)" : "translateX(0)" }}>&rarr;</span>}
    </Tag>
  );
}

import React from "react";

export interface ButtonProps {
  /** Button label / content. */
  children?: React.ReactNode;
  /** `fill` = solid violet; `outline` = hairline that fills on hover. */
  variant?: "fill" | "outline";
  size?: "sm" | "md" | "lg";
  /** Set true on obsidian surfaces so outline/hover colors invert. */
  onDark?: boolean;
  /** Show a trailing → that eases right on hover. */
  arrow?: boolean;
  /** Render as an <a> when provided. */
  href?: string;
  disabled?: boolean;
  onClick?: (e: React.MouseEvent) => void;
}

/**
 * Primary call-to-action button.
 * @startingPoint section="Core" subtitle="Filled & outline CTAs, light/dark" viewport="700x150"
 */
export function Button(props: ButtonProps): JSX.Element;

import React, { useState } from "react";

/**
 * Opportunity Designed — ButtonText
 * Quiet inline text CTA ("How I think →"). Underline offset grows, color
 * shifts to violet on hover. No fill.
 */
export function ButtonText({ children, href, onDark = false, arrow = true, onClick, ...rest }) {
  const [hover, setHover] = useState(false);
  const rest_color = onDark ? "var(--parchment)" : "var(--ink)";
  const style = {
    display: "inline-flex",
    alignItems: "center",
    gap: "0.5em",
    fontFamily: "var(--font-sans)",
    fontWeight: 500,
    fontSize: "0.9375rem",
    letterSpacing: "0.01em",
    color: hover ? (onDark ? "var(--violet-light)" : "var(--violet)") : rest_color,
    textDecoration: "underline",
    textUnderlineOffset: hover ? "6px" : "3px",
    textDecorationThickness: "1px",
    textDecorationColor: hover ? (onDark ? "var(--violet-light)" : "var(--violet)") : "var(--dusk)",
    cursor: "pointer",
    transition: "color var(--dur-fast) var(--ease-out), text-underline-offset var(--dur-base) var(--ease-out), text-decoration-color var(--dur-fast) var(--ease-out)",
  };
  const Tag = href ? "a" : "button";
  return (
    <Tag href={href} onClick={onClick} onMouseEnter={() => setHover(true)} onMouseLeave={() => setHover(false)} style={{ ...style, ...(Tag === "button" ? { background: "none", border: "none", padding: 0 } : {}) }} {...rest}>
      {children}
      {arrow && <span aria-hidden="true" style={{ transition: "transform var(--dur-base) var(--ease-out)", transform: hover ? "translateX(3px)" : "translateX(0)" }}>&rarr;</span>}
    </Tag>
  );
}

import React from "react";

export interface ButtonTextProps {
  children?: React.ReactNode;
  href?: string;
  /** Invert colors for obsidian surfaces. */
  onDark?: boolean;
  /** Trailing → (default true). */
  arrow?: boolean;
  onClick?: (e: React.MouseEvent) => void;
}

/** Quiet inline text link CTA with growing underline offset. */
export function ButtonText(props: ButtonTextProps): JSX.Element;

import React from "react";

/**
 * Opportunity Designed — Eyebrow
 * Uppercase, letter-spaced kicker above headings ("ABOUT", "CONTACT").
 */
export function Eyebrow({ children, onDark = false, accent = false, as = "div", ...rest }) {
  const Tag = as;
  return (
    <Tag
      style={{
        fontFamily: "var(--font-sans)",
        fontWeight: 600,
        fontSize: "var(--fs-meta)",
        textTransform: "uppercase",
        letterSpacing: "var(--tr-eyebrow)",
        color: accent
          ? (onDark ? "var(--violet-light)" : "var(--violet)")
          : (onDark ? "var(--dusk-2)" : "var(--dusk)"),
      }}
      {...rest}
    >
      {children}
    </Tag>
  );
}

import React from "react";

export interface EyebrowProps {
  children?: React.ReactNode;
  /** Muted taupe on light by default; dusk-2 on dark. */
  onDark?: boolean;
  /** Use violet accent color instead of muted. */
  accent?: boolean;
  as?: keyof JSX.IntrinsicElements;
}

/** Uppercase letter-spaced kicker/eyebrow label. */
export function Eyebrow(props: EyebrowProps): JSX.Element;

import React from "react";

/**
 * Opportunity Designed — SectionHead
 * Numbered section marker: a top hairline rule, a monospace-ish "01" number,
 * and an uppercase title. Mirrors the site's `.sec-head` drafting-sheet style.
 */
export function SectionHead({ num, title, onDark = false, rule = true, ...rest }) {
  const line = onDark ? "var(--border-hair-on-dark)" : "var(--border-strong)";
  const numColor = onDark ? "var(--violet-light)" : "var(--violet)";
  const titleColor = onDark ? "var(--parchment)" : "var(--ink)";
  return (
    <div
      style={{
        display: "flex",
        alignItems: "baseline",
        gap: "18px",
        borderTop: rule ? `1px solid ${line}` : "none",
        paddingTop: rule ? "16px" : 0,
      }}
      {...rest}
    >
      {num != null && (
        <span style={{ fontFamily: "var(--font-display)", fontSize: "1.05rem", letterSpacing: "0.04em", color: numColor, minWidth: "2ch" }}>{num}</span>
      )}
      <span style={{ fontFamily: "var(--font-sans)", fontWeight: 600, fontSize: "var(--fs-meta)", textTransform: "uppercase", letterSpacing: "var(--tr-eyebrow)", color: titleColor }}>{title}</span>
    </div>
  );
}

import React from "react";

export interface SectionHeadProps {
  /** Section number, e.g. "01". */
  num?: string;
  /** Uppercase title, e.g. "Ways to work together". */
  title: string;
  onDark?: boolean;
  /** Top hairline rule (default true). */
  rule?: boolean;
}

/** Numbered, uppercase section header with a top hairline rule. */
export function SectionHead(props: SectionHeadProps): JSX.Element;

import React from "react";

/**
 * Opportunity Designed — Plate
 * The brand's "card": a bordered panel with L-shaped corner registration
 * ticks in all four corners (drafting-sheet motif). Content goes inside.
 */
export function Plate({ children, onDark = false, pad = "clamp(24px,4vw,44px)", ticks = true, style, ...rest }) {
  const border = onDark ? "var(--border-hair-on-dark)" : "var(--border-hair)";
  const tickColor = onDark ? "var(--dusk-2)" : "var(--dusk)";
  const L = "var(--tick-len)";
  const W = "var(--tick-w)";
  const corner = (pos) => {
    const s = { position: "absolute", width: L, height: L, pointerEvents: "none" };
    const b = `${W} solid ${tickColor}`;
    if (pos === "tl") return { ...s, top: -1, left: -1, borderTop: b, borderLeft: b };
    if (pos === "tr") return { ...s, top: -1, right: -1, borderTop: b, borderRight: b };
    if (pos === "bl") return { ...s, bottom: -1, left: -1, borderBottom: b, borderLeft: b };
    return { ...s, bottom: -1, right: -1, borderBottom: b, borderRight: b };
  };
  return (
    <div
      style={{
        position: "relative",
        border: `1px solid ${border}`,
        borderRadius: "var(--r-sm)",
        padding: pad,
        background: onDark ? "var(--obsidian-2)" : "transparent",
        color: onDark ? "var(--parchment)" : "var(--ink)",
        ...style,
      }}
      {...rest}
    >
      {ticks && ["tl", "tr", "bl", "br"].map((p) => <span key={p} aria-hidden="true" style={corner(p)} />)}
      {children}
    </div>
  );
}

import React from "react";

export interface PlateProps {
  children?: React.ReactNode;
  onDark?: boolean;
  /** Inner padding (CSS length). */
  pad?: string;
  /** Show the four L-shaped corner registration ticks (default true). */
  ticks?: boolean;
  style?: React.CSSProperties;
}

/**
 * Bordered panel with drafting-sheet corner ticks — the brand's card.
 * @startingPoint section="Core" subtitle="Cornered 'plate' panel" viewport="700x220"
 */
export function Plate(props: PlateProps): JSX.Element;

import React from "react";

/**
 * Opportunity Designed — FigCaption
 * Drafting figure caption ("Fig. 01 · A. Morrow" / "Salt Lake City, UT").
 * A hairline-topped row with a left and (optional) right meta label.
 */
export function FigCaption({ left, right, onDark = false, ...rest }) {
  const color = onDark ? "var(--dusk-2)" : "var(--dusk)";
  const line = onDark ? "var(--border-hair-on-dark)" : "var(--border-hair)";
  return (
    <div
      style={{
        display: "flex",
        justifyContent: "space-between",
        gap: "12px",
        borderTop: `1px solid ${line}`,
        paddingTop: "8px",
        marginTop: "10px",
        fontFamily: "var(--font-sans)",
        fontWeight: 500,
        fontSize: "var(--fs-micro)",
        letterSpacing: "0.14em",
        textTransform: "uppercase",
        color,
      }}
      {...rest}
    >
      <span>{left}</span>
      {right && <span>{right}</span>}
    </div>
  );
}

import React from "react";

export interface FigCaptionProps {
  /** e.g. "Fig. 01 · A. Morrow" */
  left: React.ReactNode;
  /** e.g. "Salt Lake City, UT" */
  right?: React.ReactNode;
  onDark?: boolean;
}

/** Uppercase drafting-style figure caption row under an image/plate. */
export function FigCaption(props: FigCaptionProps): JSX.Element;

import React from "react";

/**
 * Opportunity Designed — Tag
 * Small monospace-register status/code chip ("Case study 01", "30-day
 * engagement", "Signature · 90+ day build").
 */
export function Tag({ children, tone = "default", onDark = false, ...rest }) {
  const tones = {
    default: {
      color: onDark ? "var(--parchment)" : "var(--ink)",
      border: onDark ? "var(--border-hair-on-dark)" : "var(--border-strong)",
      bg: "transparent",
    },
    accent: {
      color: onDark ? "var(--violet-light)" : "var(--violet)",
      border: "var(--violet)",
      bg: onDark ? "transparent" : "var(--violet-tint)",
    },
    solid: {
      color: "var(--parchment)",
      border: "var(--violet)",
      bg: "var(--violet)",
    },
  };
  const t = tones[tone] || tones.default;
  return (
    <span
      style={{
