export function Field({ label, required = false, type = "text", textarea = false, placeholder, onDark = false, ...rest }) {
  const [focus, setFocus] = useState(false);
  const labelColor = onDark ? "var(--dusk-2)" : "var(--dusk)";
  const textColor = onDark ? "var(--parchment)" : "var(--ink)";
  const base = onDark ? "var(--border-hair-on-dark)" : "var(--border-strong)";
  const control = {
    width: "100%",
    boxSizing: "border-box",
    fontFamily: "var(--font-sans)",
    fontWeight: 400,
    fontSize: "1rem",
    color: textColor,
    background: "transparent",
    border: "none",
    borderBottom: `1.5px solid ${focus ? "var(--violet)" : base}`,
    padding: "10px 2px",
    outline: "none",
    borderRadius: 0,
    transition: "border-color var(--dur-fast) var(--ease-out)",
    resize: textarea ? "vertical" : undefined,
    minHeight: textarea ? "120px" : undefined,
  };
  return (
    <label style={{ display: "block" }}>
      <span style={{ display: "block", fontFamily: "var(--font-sans)", fontWeight: 600, fontSize: "var(--fs-meta)", textTransform: "uppercase", letterSpacing: "0.16em", color: labelColor, marginBottom: "8px" }}>
        {label}{required && <span style={{ color: "var(--dusk)", fontWeight: 400 }}> (required)</span>}
      </span>
      {textarea
        ? <textarea placeholder={placeholder} onFocus={() => setFocus(true)} onBlur={() => setFocus(false)} style={control} {...rest} />
        : <input type={type} placeholder={placeholder} onFocus={() => setFocus(true)} onBlur={() => setFocus(false)} style={control} {...rest} />}
    </label>
  );
}

