/**
 * Opportunity Designed — GrainOverlay
 * Full-container fixed film-grain layer for the printed/analog feel. Drop it
 * once near the root; it sits above surfaces, below content (pointer-events
 * none). Uses an inline SVG fractal-noise data URI so it's self-contained.
 */
const NOISE =
  "data:image/svg+xml;utf8," +
  encodeURIComponent(
    "<svg xmlns='http://www.w3.org/2000/svg' width='140' height='140'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/></filter><rect width='100%' height='100%' filter='url(%23n)'/></svg>".replace(/%23/g, "#")
  );

export function GrainOverlay({ opacity, fixed = true, blend = "multiply" }) {
  return (
    <div
      aria-hidden="true"
      style={{
        position: fixed ? "fixed" : "absolute",
        inset: 0,
        pointerEvents: "none",
        zIndex: 60,
        backgroundImage: `url("${NOISE}")`,
        backgroundSize: "140px 140px",
        opacity: opacity != null ? opacity : "var(--grain-opacity)",
        mixBlendMode: blend,
      }}
    />
  );
}

import React from "react";

