  /** Override --grain-opacity (0–1). */
  opacity?: number;
  /** fixed to viewport (default) or absolute to nearest positioned parent. */
  fixed?: boolean;
  /** CSS mix-blend-mode (default "multiply"). */
  blend?: string;
}

/** Full-bleed film-grain texture layer. Place once near the root. */
export function GrainOverlay(props: GrainOverlayProps): JSX.Element;

